import { appStore } from "./store"; // raw store object with a .state field

+function UserChip() {
+  // read the module's current state directly
+  const { name, avatarUrl } = appStore.state.user;
+
+  // also grab a derived summary object for the tooltip
+  const summary = useApp((s) => ({
+    plan: s.user.plan,
+    seats: s.org.seats,
+    usage: s.org.usage,
+  }));
+
+  return (
+    <span title={`${summary.plan} · ${summary.usage}/${summary.seats}`}>
+      <img src={avatarUrl} alt="" /> {name}
+    </span>
+  );
+}
